{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "The bill would change the definition of “bullying” in Tennessee Code section 39-17-308(e) to cover acts by school employees against students and acts by students against other students. The act must substantially interfere with the victim’s educational benefits, opportunities, or performance. On school grounds, at a school activity, on school-provided equipment or transportation, or at an official school bus stop, it must also cause physical harm or property damage, or knowingly place the victim in reasonable fear of either. Off school property or outside a school activity, it must be directed at a specific victim and substantially disrupt the educational environment or learning process.",
      "rationale": "Conveys the amended definition, covered actors, educational interference requirement, and both location-specific sets of conditions."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "“School employee” would include employees of private schools, local education agencies, public charter schools, and other public schools.",
      "rationale": "Includes every category of employer covered by the new definition."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "The bill would change the definition of “bullying” in Tennessee Code section 39-17-308(e) to cover acts by school employees against students and acts by students against other students.",
      "rationale": "Conveys both actor-dependent categories of student victims, although it integrates them into the discussion of bullying rather than separately labeling the victim definition."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "The bill would add “and school employee” after “each student” in section 49-6-4503(b)(3).",
      "rationale": "Identifies the exact insertion and its statutory target."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "It would make a teacher or school employee found to have committed harassment, intimidation, bullying, or cyberbullying subject to dismissal or suspension.",
      "rationale": "Conveys the covered employees, required finding, all four types of conduct, and both possible disciplinary consequences."
    },
    {
      "proposition_id": "P6",
      "status": "partial",
      "summary_quote": "It would also add committing such an act in violation of a school district policy to section 49-5-501(7).",
      "rationale": "Identifies the statutory target and policy-violating conduct, but omits that the policy must be adopted in accordance with Title 49, Chapter 6, Part 45, rather than simply any school district policy."
    },
    {
      "proposition_id": "P7",
      "status": "full",
      "summary_quote": "The bill would take effect July 1, 2026, and apply to acts committed on or after that date.",
      "rationale": "States both the effective date and the prospective applicability condition."
    }
  ]
}
